import {SIGNAL_CATALOG} from './signal-junctions.js';
import {signalizedJunctions,junctionsInRadius,candidateForStudy,defaultArmSettings,createJunctionPlan} from './junction-analysis.js';
import {distanceM,laneEnvelope,laneCrossSection} from './geometry.js';
import {createVectorBase} from './vector-map.js';
import {escapeHTML as esc} from './operations-ui.js';

export const AREA_CANDIDATES=SIGNAL_CATALOG.junctions;
export const AREA_SOURCE=SIGNAL_CATALOG.source;
export function areaPlannerHTML(){return `<div class="title-row"><div><span class="eyebrow">INSTALLATION / AREA PLANNER</span><h1>Choose a signalized intersection.</h1><p class="subtitle">Traffic lights only. Select an intersection to customize its puck arrangement.</p></div></div><div class="installation-mode-switch" role="group" aria-label="Installation workspace"><button class="button dark" aria-pressed="true" data-action="install-area-mode">Area planner</button><button class="button" data-action="install-road-mode">Configured sites</button><button class="button" data-action="install-beacon-mode">Vehicle beacons</button><button class="button" data-action="install-devices-mode">Install devices</button></div><div class="area-controls"><label>Analysis radius<select id="area-radius" aria-label="Analysis radius"><option value="2000">2 km</option><option value="5000" selected>5 km</option><option value="10000">10 km</option></select></label><label class="area-search">Find an intersection<input id="area-search" type="search" placeholder="Road name or intersection ID"></label><label>Show<select id="area-filter" aria-label="Show"><option value="all">All signalized intersections</option><option value="saved">Saved plans</option></select></label><span id="area-result-count" role="status"></span></div><div class="area-planner-grid"><section class="panel"><div class="panel-head"><div><span class="eyebrow">MANDAUE / STUDY CORRIDOR CENTRE</span><h2>Signalized intersections</h2></div><button class="button small" id="area-fit">Fit analysis area</button></div><div class="geometry-view-bar"><div class="map-base-switch" role="group" aria-label="Area map appearance"><button id="area-clean" aria-pressed="true">Clean geometry</button><button id="area-satellite" aria-pressed="false">Satellite reference</button></div><span>Click a junction · hover a puck for its ID</span></div><div id="area-map" class="geo-map" aria-label="Traffic-light intersections and installation templates"></div><div class="area-legend"><span><i class="area-dot"></i> Mapped traffic lights</span><span><i class="area-dot study"></i> Configured study site</span><span><i class="area-dot saved"></i> Saved plan</span><span>○ Radius from corridor centre</span></div><div id="area-junction-list" class="area-junction-list" aria-label="Selectable intersections"></div></section><section class="panel area-selection-panel"><div class="panel-head"><h2>Installation template</h2><span class="badge blue" id="area-plan-state">SELECT A JUNCTION</span></div><div id="area-selection" class="panel-body"><div class="installation-empty"><div class="pick-symbol">⌖</div><h3>Start on the map</h3><p>Hover a traffic-light intersection for its name. Click it to place the 5 / 30 / 60 m upstream template and one downstream counter per outgoing lane.</p><p class="hint">Pucks are centred between the planned lane borders. Adjust the lane details after selecting.</p></div></div></section></div><details class="handoff-detail subsection area-method"><summary>Analysis coverage and placement basis</summary><div class="panel-body"><p>Signal-centered road geometry from OpenStreetMap, retrieved 31 October 2026. Radius is measured from the study corridor centre (${AREA_SOURCE.center.join(', ')}); coverage extends to 10 km, with 5 km selected initially. This circle is a search area, not an agency jurisdiction boundary.</p><p>Only junctions with mapped vehicle traffic-light evidence, plus the three established signalized study sites, are selectable. Ordinary unsignalized junctions are excluded. Shared road nodes identify junctions; connected fragments are consolidated. Map crossings without a shared node are not treated as junctions. Missing lane tags use an editable one-lane-per-direction assumption. Signal evidence comes from highway=traffic_signals on the connected motor-road graph. Pedestrian-crossing tags alone do not qualify. A signal is assigned to only its nearest connected junction group. Map evidence still needs authority confirmation.</p><p>Automatic signal references are 12 m along each road arm from its junction node. The 5 / 30 / 60 m stations follow each lane path from that reference. Adjust the reference, counts and widths against imagery and the site. Short or ambiguous paths are flagged rather than extended into invented roads. Nearby side junctions require review.</p><p>New plans are saved separately from the three active study sites and included in Workspace export. Existing study layouts open in Configured sites. Previously saved non-signalized plans remain in project exports but are excluded from this planner. No field installation is activated by browsing.</p><a href="./downloads/AREA_INSTALLATION.md" download>Download analysis and installation guide ↗</a></div></details>`;}

export class AreaPlanner{
 constructor({project,state={},onSave,onOpenStudy,onOpenDevices,onExport,onError}){this.project=project;this.state=state;this.onSave=onSave;this.onOpenStudy=onOpenStudy;this.onOpenDevices=onOpenDevices;this.onExport=onExport;this.onError=onError;this.radius=[2000,5000,10000].includes(state.radius)?state.radius:5000;this.selected=null;this.plan=null;this.settings=null;this.showCoordinates=false;this.invalidFields=new Set();this.map=null;this.abort=new AbortController();}
 mount(){
  const L=window.L;if(!L)return;this.map=L.map('area-map',{maxZoom:21,minZoom:10,zoomSnap:.25,zoomDelta:.5}).setView(AREA_SOURCE.center,16);
  this.map.getContainer().classList.add('area-geometry');this.clean=createVectorBase(L,this.project).addTo(this.map);this.satellite=L.tileLayer('https://services.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxNativeZoom:19,maxZoom:21,attribution:'Imagery © Esri, Vantor, Earthstar Geographics & GIS User Community'});L.control.scale({imperial:false}).addTo(this.map);this.map.attributionControl.addAttribution('Road analysis © <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>');
  this.targets=L.layerGroup().addTo(this.map);this.overlay=L.layerGroup().addTo(this.map);this.radiusLayer=L.circle(AREA_SOURCE.center,{radius:this.radius,color:'#e6be60',weight:1.5,opacity:.65,fillColor:'#e6be60',fillOpacity:.025,interactive:false}).addTo(this.map);
  const root=document.querySelector('#main');this.listen(root,'click',e=>{const choice=e.target.closest('[data-area-candidate]');if(choice){this.select(choice.dataset.areaCandidate);document.querySelector('.area-planner-grid').scrollIntoView({block:'start',behavior:'smooth'});return;}if(e.target.closest('#area-fit'))this.fit();if(e.target.closest('#area-clean'))this.setBase(false);if(e.target.closest('#area-satellite'))this.setBase(true);if(e.target.closest('#area-save'))this.save();if(e.target.closest('#area-export')&&this.plan)this.onExport(this.plan);if(e.target.closest('#area-open-study'))this.onOpenStudy(this.study.id);if(e.target.closest('#area-install-devices'))this.onOpenDevices(this.study?.id||this.plan.id);});
  this.listen(root,'input',e=>{if(e.target.id==='area-search')this.refreshCandidates();else if(e.target.matches('[data-arm-field]'))this.updateSettings(e.target,true);});
  this.listen(root,'change',e=>{if(e.target.id==='area-radius'){this.radius=Number(e.target.value);this.state.radius=this.radius;this.radiusLayer.setRadius(this.radius);this.refreshCandidates();this.fit();}if(e.target.id==='area-filter')this.refreshCandidates();if(e.target.id==='area-coordinates'){this.showCoordinates=e.target.checked;this.drawPlan();}if(e.target.matches('[data-arm-field]'))this.updateSettings(e.target);});
  document.querySelector('#area-radius').value=String(this.radius);this.refreshCandidates();this.fit();if(this.state.selectedId)this.select(this.state.selectedId,false);
 }
 listen(element,event,fn){element.addEventListener(event,fn,{signal:this.abort.signal});}
 setBase(satellite){const active=satellite?this.satellite:this.clean,inactive=satellite?this.clean:this.satellite;this.map.removeLayer(inactive);active.addTo(this.map);this.map.getContainer().classList.toggle('area-geometry',!satellite);document.querySelector('#area-clean').setAttribute('aria-pressed',String(!satellite));document.querySelector('#area-satellite').setAttribute('aria-pressed',String(satellite));}
 fit(){this.map.fitBounds(this.radiusLayer.getBounds(),{padding:[18,18],animate:false});}
 visibleCandidates(){const q=document.querySelector('#area-search').value.toLowerCase().trim(),filter=document.querySelector('#area-filter').value;return junctionsInRadius(signalizedJunctions(AREA_CANDIDATES,this.project),AREA_SOURCE.center,this.radius,AREA_SOURCE.max_radius_m).filter(c=>(!q||c.name.toLowerCase().includes(q)||c.id.toLowerCase().includes(q))&&(filter!=='saved'||this.project.installation_plans?.some(p=>p.id===c.id))).sort((a,b)=>distanceM(a.point,AREA_SOURCE.center)-distanceM(b.point,AREA_SOURCE.center));}
 refreshCandidates(){
  const L=window.L;this.targets.clearLayers();const visible=this.visibleCandidates();document.querySelector('#area-result-count').textContent=`${visible.length} signalized intersection${visible.length===1?'':'s'} · ${this.radius/1000} km radius`;
  for(const c of visible){const study=candidateForStudy(c,this.project),saved=this.project.installation_plans?.some(p=>p.id===c.id),selected=this.selected?.id===c.id,color=selected?'#ffc966':study?'#64d4bc':saved?'#d1b6ff':'#8db7d6';const marker=L.circleMarker(c.point,{radius:selected?10:study?8:6,className:'area-junction-target',color,weight:selected?3:1.5,fillColor:color,fillOpacity:selected?.55:.7,bubblingMouseEvents:false}).addTo(this.targets);
   marker.bindTooltip(`<strong>${esc(study?.mapped_name||c.name)}</strong><br>${esc(c.id)} · ${study?'Configured study site':saved?'Saved installation plan':'Mapped traffic lights'}<br>Click to preview`,{className:'area-junction-tooltip',direction:'top'});marker.on('mouseover',()=>marker.setStyle({weight:3,radius:10}));marker.on('mouseout',()=>marker.setStyle({weight:selected?3:1.5,radius:selected?10:study?8:6}));marker.on('click',()=>this.select(c.id));
   const element=marker.getElement();element?.setAttribute('role','button');element?.setAttribute('tabindex','0');element?.setAttribute('aria-label',`Preview ${study?.mapped_name||c.name} (${c.id})`);element?.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();this.select(c.id);}});
  }
  const list=document.querySelector('#area-junction-list');list.innerHTML=visible.length?visible.map(c=>`<button data-area-candidate="${esc(c.id)}" class="${c.id===this.selected?.id?'selected':''}"><strong>${esc(candidateForStudy(c,this.project)?.mapped_name||c.name)}</strong><small>${esc(c.id)} · ${candidateForStudy(c,this.project)?'Configured study':'Traffic lights mapped'}${this.project.installation_plans?.some(p=>p.id===c.id)?' · Saved':''}</small></button>`).join(''):'<div class="empty">No signalized intersections match these filters.</div>';
  if(this.selected&&!junctionsInRadius([this.selected],AREA_SOURCE.center,this.radius,AREA_SOURCE.max_radius_m).length)this.clearSelection();
 }
 clearSelection(){this.selected=null;this.plan=null;this.state.selectedId=null;this.overlay.clearLayers();document.querySelector('#area-selection').innerHTML='<div class="empty">Select a signalized intersection inside the analysis radius.</div>';document.querySelector('#area-plan-state').textContent='SELECT A JUNCTION';}
 select(id,fit=true){
  const c=AREA_CANDIDATES.find(c=>c.id===id);if(!c||!signalizedJunctions(AREA_CANDIDATES,this.project).some(x=>x.id===id)||distanceM(c.point,AREA_SOURCE.center)>this.radius)return;this.selected=c;this.invalidFields.clear();this.state.selectedId=id;this.study=candidateForStudy(c,this.project);const saved=this.project.installation_plans?.find(p=>p.id===id);this.settings=copy(saved?.settings||defaultArmSettings(c));
  this.plan=this.study?{id:this.study.id,name:this.study.mapped_name||this.study.name,site:this.study,devices:this.project.devices.filter(d=>d.intersection_id===this.study.id&&d.role==='sensor'),issues:[],warnings:[],status:'configured'}:createJunctionPlan(c,this.settings);
  this.showCoordinates=false;this.renderSelection();this.refreshCandidates();this.drawPlan(fit);
 }
 renderSelection(){
  const p=this.plan,c=this.selected,box=document.querySelector('#area-selection');document.querySelector('#area-plan-state').textContent=this.study?'CONFIGURED STUDY':this.project.installation_plans?.some(p=>p.id===c.id)?'SAVED PLAN':'NEW TEMPLATE';
  box.innerHTML=`<div class="area-selected-heading"><h3>${esc(p.name)}</h3><span class="mono">${esc(c.id)}</span></div><div class="installation-counts"><div><strong>${p.devices.length}</strong><span>Planned pucks</span></div><div><strong>${p.site.lanes.filter(l=>l.flow==='inbound').length} / ${p.site.lanes.filter(l=>l.flow==='outbound').length}</strong><span>Incoming / outgoing lanes</span></div></div><p class="area-placement-rule"><b>5 · 30 · 60 m</b> upstream per incoming lane<br><b>1 counter</b> per outgoing lane · 10 m downstream</p><div id="area-plan-issues">${this.issueHTML()}</div>${this.study?`<p class="hint">This crossing uses your existing study layout and saved adjustments.</p><div class="vehicle-actions"><button class="button dark" id="area-install-devices">Install devices →</button><button class="button" id="area-open-study">Customize study devices ↗</button></div>`:`<div class="area-arm-editor"><h4>Customize road arms</h4><p class="hint">In = towards the junction · Out = away from it</p>${c.arms.map((a,i)=>`<fieldset><legend>${i+1}. ${esc(a.name)}</legend><small>${esc(a.lane_source)}</small><div class="area-arm-fields">${[['inbound','In lanes','0','8','1'],['outbound','Out lanes','0','8','1'],['width_m','Width (m)','2.2','4.5','.1'],['reference_m','Reference (m)','0','40','1']].map(([key,label,min,max,step])=>`<label>${label}<input type="number" min="${min}" max="${max}" step="${step}" value="${this.settings[a.id][key]}" data-arm-id="${esc(a.id)}" data-arm-field="${key}" aria-label="${esc(a.name)} arm ${i+1} ${label}"></label>`).join('')}</div></fieldset>`).join('')}</div><div class="vehicle-actions"><button class="button dark" id="area-save" ${p.issues.length?'disabled':''}>Save installation plan</button><button class="button" id="area-export" ${p.issues.length?'disabled':''}>Export plan</button></div><button class="button dark area-install-next" id="area-install-devices" ${!this.project.installation_plans?.some(saved=>saved.id===c.id)||p.issues.length?'disabled':''}>Install devices →</button><p class="hint">Save this plan, then select a component and connect it over USB.</p>`}<details class="area-coordinate-option"><summary>Position details</summary><label><input id="area-coordinates" type="checkbox"> Show coordinates on puck hover</label><p>Latitude / longitude: WGS84. X / Y: metres east / north of this junction.</p><span class="mono">${c.point.map(n=>n.toFixed(7)).join(', ')}</span></details><div id="area-puck-detail" class="area-puck-detail"><span>Hover for an ID. Click a puck for its position.</span></div>`;
 }
 issueHTML(){return this.plan.issues.length?`<div class="notice">${this.plan.issues.map(x=>`<p>${esc(x)}</p>`).join('')}</div>`:`<div class="area-plan-note">${this.study?'Existing study geometry':'Lane-centred template · check signal references'}${this.plan.warnings?.length?`<details><summary>Nearby junctions need review</summary>${this.plan.warnings.map(x=>`<p>${esc(x)}</p>`).join('')}</details>`:''}</div>`;}
 updateSettings(input,quiet=false){try{const next=copy(this.settings);for(const field of document.querySelectorAll('[data-arm-field]')){field.setCustomValidity('');if(field.value.trim()==='')throw Error('Enter a value for each lane setting.');next[field.dataset.armId][field.dataset.armField]=Number(field.value);}const plan=createJunctionPlan(this.selected,next);this.settings=next;this.plan=plan;this.invalidFields.clear();document.querySelector('#area-plan-issues').innerHTML=this.issueHTML();document.querySelector('#area-save').disabled=plan.issues.length>0||this.invalidFields.size>0;document.querySelector('#area-export').disabled=plan.issues.length>0||this.invalidFields.size>0;const counts=document.querySelectorAll('#area-selection .installation-counts strong');counts[0].textContent=plan.devices.length;counts[1].textContent=`${plan.site.lanes.filter(l=>l.flow==='inbound').length} / ${plan.site.lanes.filter(l=>l.flow==='outbound').length}`;document.querySelector('#area-plan-state').textContent='UNSAVED CHANGES';document.querySelector('#area-install-devices').disabled=true;this.drawPlan();}catch(e){this.invalidFields.add(input);document.querySelector('#area-save').disabled=true;document.querySelector('#area-export').disabled=true;document.querySelector('#area-install-devices').disabled=true;input.setCustomValidity(e.message);if(!quiet){input.reportValidity();this.onError(e.message);}}}
 position(d){const c=this.selected.point,rad=Math.PI/180;return {lat:d.latitude,lon:d.longitude,x:(d.longitude-c[1])*rad*6371008.8*Math.cos(c[0]*rad),y:(d.latitude-c[0])*rad*6371008.8};}
 drawPlan(fit=false){
  const L=window.L;this.overlay.clearLayers();if(!this.plan)return;const points=[];
  for(const lane of this.plan.site.lanes){const band=laneEnvelope(lane,lane.flow==='inbound'?65:18);points.push(...band.left,...band.right);L.polygon([...band.left,...[...band.right].reverse()],{weight:0,fillColor:lane.flow==='inbound'?'#dcb078':'#8de0d0',fillOpacity:.07,interactive:false}).addTo(this.overlay);for(const edge of [band.left,band.right])L.polyline(edge,{color:'#fff',weight:1.2,opacity:.7,dashArray:'6 5',interactive:false}).addTo(this.overlay);L.circleMarker(lane.path[0],{radius:2,color:'#b4c5d4',weight:1,interactive:false}).addTo(this.overlay);}
  for(const d of this.plan.devices){const lane=this.plan.site.lanes.find(l=>l.id===d.lane_id),pos=this.position(d),label=d.placement==='upstream'?`${d.offset_m} m upstream`:'Downstream counter',marker=L.marker([d.latitude,d.longitude],{icon:L.divIcon({className:'area-puck-marker',html:`<span class="${d.placement==='downstream'?'out':''}"></span>`,iconSize:[20,20],iconAnchor:[10,10]}),title:`${d.id} · ${label}`}).addTo(this.overlay);marker.bindTooltip(`<strong>${esc(d.id)}</strong><br>${esc(lane.road_name)} · ${lane.flow==='inbound'?'incoming':'outgoing'} lane ${lane.lane_number}<br>${label}${this.showCoordinates?`<br>${pos.lat.toFixed(7)}, ${pos.lon.toFixed(7)}<br>X ${pos.x.toFixed(1)} m · Y ${pos.y.toFixed(1)} m`:''}`,{className:'area-puck-tooltip',direction:'top',offset:[0,-6]});marker.on('click',()=>{const cross=laneCrossSection(lane,d.offset_m);document.querySelector('#area-puck-detail').innerHTML=`<strong>${esc(d.id)}</strong><dl><dt>Station</dt><dd>${label}</dd><dt>Lane centre</dt><dd>${(lane.lane_width_m/2).toFixed(2)} m to each border</dd><dt>Latitude</dt><dd>${pos.lat.toFixed(7)}</dd><dt>Longitude</dt><dd>${pos.lon.toFixed(7)}</dd><dt>Local X / Y</dt><dd>${pos.x.toFixed(1)} / ${pos.y.toFixed(1)} m</dd></dl><small>Planning ID · physical hardware UID not assigned</small>`;});}
  if(fit&&points.length)this.map.fitBounds(L.latLngBounds(points).pad(.08),{padding:[24,24],maxZoom:20,animate:false});
 }
 save(){try{const next=copy(this.settings);for(const input of document.querySelectorAll('[data-arm-field]')){if(input.value.trim()==='')throw Error('Enter a value for each lane setting.');next[input.dataset.armId][input.dataset.armField]=Number(input.value);}const plan=createJunctionPlan(this.selected,next);if(plan.issues.length)throw Error('Resolve the geometry issues before saving.');this.settings=next;this.plan=plan;this.project=this.onSave(this.plan);this.renderSelection();this.refreshCandidates();}catch(e){this.onError(e.message);}}
 destroy(){this.abort.abort();this.map?.remove();}
}
const copy=x=>JSON.parse(JSON.stringify(x));
